import pandas as pdfrom datetime import datetime, timedelta, datefrom pathlib import Path# ==== USER SETTING: folder with all your Excel files ====folder_path = Path("/Users/mirandahulsey-vincent/Documents/allPythonCode/BYOD_class_clean/data_inputs/eugene_daylight_hours/")# List to hold all records from all monthsall_records = []# Loop over matching Excel filesfor file_path in sorted(folder_path.glob("*eugene-oregon-usa-sunrise-and-sunset-calendar-bluegrey-sunday-start-en.xlsx")):    print(f"Processing file: {file_path.name}")        # Extract year and month from filename    filename_parts = file_path.name.split("-")    try:        year = int(filename_parts[0])        month_number = int(filename_parts[1])    except (ValueError, IndexError):        print(f"Could not parse year/month from filename: {file_path.name}")        continue    # Load the Excel sheet    df = pd.read_excel(file_path, sheet_name=None, header=None)    sheet_name = list(df.keys())[0]    df = df[sheet_name]    # List to store records for this file    records = []    # Iterate over all cells    for col in range(df.shape[1]):        row = 0        while row < df.shape[0]:            date_cell = df.iloc[row, col]            if pd.isna(date_cell):                row += 1                continue            try:                day_of_month = int(date_cell)            except (ValueError, TypeError):                row += 1                continue            if not (1 <= day_of_month <= 31):                row += 1                continue            # Info cell: prefer cell below            info_cell = None            if row + 1 < df.shape[0]:                info_cell = df.iloc[row + 1, col]            if pd.isna(info_cell):                # Try cell to the right                if col + 1 < df.shape[1]:                    info_cell = df.iloc[row, col + 1]            if pd.isna(info_cell) or not isinstance(info_cell, str) or "Sunrise" not in info_cell:                row += 1                continue            # Parse info            info_lines = str(info_cell).split("\n")            sunrise = ""            sunset = ""            daylight = ""            for line in info_lines:                line = line.strip()                if line.startswith("Sunrise:"):                    sunrise = line.replace("Sunrise:", "").strip()                elif line.startswith("Sunset:"):                    sunset = line.replace("Sunset:", "").strip()                elif line.startswith("Daylight:"):                    daylight = line.replace("Daylight:", "").strip()            date_str = datetime(year, month_number, day_of_month).strftime("%m-%d-%Y")            records.append({                "Date": date_str,                "Sunrise": sunrise,                "Sunset": sunset,                "Daylight": daylight            })            row += 2    all_records.extend(records)# === Create combined DataFrame ===calendar_df = pd.DataFrame(all_records)# === Convert Date to datetime and sort ===calendar_df["Date_dt"] = pd.to_datetime(calendar_df["Date"], format="%m-%d-%Y")calendar_df = calendar_df.sort_values("Date_dt").reset_index(drop=True)# === Convert Sunrise/Sunset times to minutes since midnight ===def parse_time_to_minutes(time_str):    if pd.isna(time_str) or not isinstance(time_str, str) or time_str.strip() == "":        return None    try:        t = datetime.strptime(time_str.strip(), "%I:%M %p")        return t.hour * 60 + t.minute    except Exception as e:        print(f"Error parsing time: {time_str} - {e}")        return Nonecalendar_df["Sunrise_min"] = calendar_df["Sunrise"].apply(parse_time_to_minutes)calendar_df["Sunset_min"] = calendar_df["Sunset"].apply(parse_time_to_minutes)# === Assign each date to ISO Year-Week ===calendar_df["Year_Week"] = calendar_df["Date_dt"].dt.strftime("%G-W%V")# === Compute average sunrise and sunset per week ===weekly_avg_df = (    calendar_df.groupby("Year_Week")    .agg({        "Sunrise_min": "mean",        "Sunset_min": "mean",        "Date_dt": "min"    })    .reset_index())# === Convert minutes back to time strings ===def minutes_to_time_str(minutes):    if pd.isna(minutes):        return ""    minutes = int(round(minutes))    hour = (minutes // 60) % 24    minute = minutes % 60    dt = datetime(1900, 1, 1, hour, minute)    return dt.strftime("%-I:%M %p")weekly_avg_df["Avg_Sunrise"] = weekly_avg_df["Sunrise_min"].apply(minutes_to_time_str)weekly_avg_df["Avg_Sunset"] = weekly_avg_df["Sunset_min"].apply(minutes_to_time_str)# === Compute daylight duration ===def compute_daylight_str(sunrise_min, sunset_min):    if pd.isna(sunrise_min) or pd.isna(sunset_min):        return ""    diff = sunset_min - sunrise_min    if diff < 0:        diff += 1440    hours = int(diff // 60)    minutes = int(diff % 60)    return f"{hours:02d}:{minutes:02d}"weekly_avg_df["Daylight"] = weekly_avg_df.apply(    lambda row: compute_daylight_str(row["Sunrise_min"], row["Sunset_min"]),    axis=1)# === Select final columns ===average_week_df = weekly_avg_df[[    "Date_dt",    "Avg_Sunrise",    "Avg_Sunset",    "Daylight"]].sort_values("Date_dt").reset_index(drop=True)# === Function to round time strings to nearest 15 min ===def round_time_str_to_nearest_15min(time_str):    if pd.isna(time_str) or not isinstance(time_str, str) or time_str.strip() == "":        return ""    try:        t = datetime.strptime(time_str, "%I:%M %p")        total_minutes = t.hour * 60 + t.minute        rounded_minutes = int(round(total_minutes / 15.0) * 15)        if rounded_minutes == 1440:            rounded_minutes = 0        hour = rounded_minutes // 60        minute = rounded_minutes % 60        dt = datetime(1900, 1, 1, hour, minute)        return dt.strftime("%-I:%M %p")    except Exception as e:        print(f"Error rounding time: {time_str} - {e}")        return time_str# === Create rounded DataFrame ===rounded_average_week_df = average_week_df.copy()rounded_average_week_df["Avg_Sunrise"] = rounded_average_week_df["Avg_Sunrise"].apply(round_time_str_to_nearest_15min)rounded_average_week_df["Avg_Sunset"] = rounded_average_week_df["Avg_Sunset"].apply(round_time_str_to_nearest_15min)# === DST-included schedule ===DST_included_light_change_schedule = (    rounded_average_week_df    .groupby(["Avg_Sunrise", "Avg_Sunset"])    .agg({"Date_dt": "min"})    .reset_index()    .sort_values("Date_dt")    .reset_index(drop=True))# === Create NO DST schedule ===def adjust_for_no_dst(row):    dt = row["Date_dt"].date()    dst_start = date(2025, 3, 9)    dst_end = date(2025, 11, 1)    sunrise_min = row["Sunrise_min"]    sunset_min = row["Sunset_min"]    if dst_start <= dt <= dst_end:        if pd.notna(sunrise_min):            sunrise_min -= 60        if pd.notna(sunset_min):            sunset_min -= 60    if pd.notna(sunrise_min) and sunrise_min < 0:        sunrise_min += 1440    if pd.notna(sunset_min) and sunset_min < 0:        sunset_min += 1440    return pd.Series({"Sunrise_min_adj": sunrise_min, "Sunset_min_adj": sunset_min})unrounded_avg_df = average_week_df.copy()unrounded_avg_df["Sunrise_min"] = average_week_df["Avg_Sunrise"].apply(parse_time_to_minutes)unrounded_avg_df["Sunset_min"] = average_week_df["Avg_Sunset"].apply(parse_time_to_minutes)adjusted_times = unrounded_avg_df.apply(adjust_for_no_dst, axis=1)unrounded_avg_df["Sunrise_min_adj"] = adjusted_times["Sunrise_min_adj"]unrounded_avg_df["Sunset_min_adj"] = adjusted_times["Sunset_min_adj"]unrounded_avg_df["Avg_Sunrise_NO_DST"] = unrounded_avg_df["Sunrise_min_adj"].apply(minutes_to_time_str)unrounded_avg_df["Avg_Sunset_NO_DST"] = unrounded_avg_df["Sunset_min_adj"].apply(minutes_to_time_str)unrounded_avg_df["Avg_Sunrise_NO_DST"] = unrounded_avg_df["Avg_Sunrise_NO_DST"].apply(round_time_str_to_nearest_15min)unrounded_avg_df["Avg_Sunset_NO_DST"] = unrounded_avg_df["Avg_Sunset_NO_DST"].apply(round_time_str_to_nearest_15min)NO_DST_light_change_schedule = (    unrounded_avg_df    .groupby(["Avg_Sunrise_NO_DST", "Avg_Sunset_NO_DST"])    .agg({"Date_dt": "min"})    .reset_index()    .sort_values("Date_dt")    .reset_index(drop=True))# === Prepare combined schedule with clean date format ===dst_df = DST_included_light_change_schedule.rename(columns={    "Avg_Sunrise": "holding lights ON (adjusted by TeACS)",    "Avg_Sunset": "holding lights OFF (adjusted by TeACS)",    "Date_dt": "Date"})no_dst_df = NO_DST_light_change_schedule.rename(columns={    "Avg_Sunrise_NO_DST": "recording chamber lights ON (adjusted by Rose)",    "Avg_Sunset_NO_DST": "recording chamber lights OFF (adjusted by Rose)",    "Date_dt": "Date"})dst_df["Date"] = dst_df["Date"].dt.strftime("%Y-%m-%d")no_dst_df["Date"] = no_dst_df["Date"].dt.strftime("%Y-%m-%d")combined_schedule = pd.merge(    dst_df,    no_dst_df,    on="Date",    how="outer").sort_values("Date").reset_index(drop=True)combined_schedule = combined_schedule[[    "Date",    "holding lights ON (adjusted by TeACS)",    "holding lights OFF (adjusted by TeACS)",    "recording chamber lights ON (adjusted by Rose)",    "recording chamber lights OFF (adjusted by Rose)"]]# === Compute daylight hours based on NO DST times ===def time_str_to_minutes(time_str):    if pd.isna(time_str) or not isinstance(time_str, str) or time_str.strip() == "":        return None    try:        t = datetime.strptime(time_str.strip(), "%I:%M %p")        return t.hour * 60 + t.minute    except Exception as e:        print(f"Error parsing time: {time_str} - {e}")        return Nonedef compute_hours_of_daylight(row):    sunrise_min = time_str_to_minutes(row["recording chamber lights ON (adjusted by Rose)"])    sunset_min = time_str_to_minutes(row["recording chamber lights OFF (adjusted by Rose)"])    if sunrise_min is None or sunset_min is None:        return ""    diff = sunset_min - sunrise_min    if diff < 0:        diff += 1440    return round(diff / 60.0, 2)combined_schedule["Daylight Hours (NO DST)"] = combined_schedule.apply(    compute_hours_of_daylight,    axis=1)# === Save to Excel inside folder_path ===output_path = folder_path / "Combined_Lighting_Schedule.xlsx"combined_schedule.to_excel(output_path, index=False)print(f"\n✅ Combined schedule saved to: {output_path}")